import { findOrder, type OrderRecord } from './db'

function describeStatus(status: OrderRecord['status']): string {
  switch (status) {
    case 'pending':
      return 'awaiting payment'
    case 'paid':
      return 'paid'
    default: {
      const exhaustive: never = status
      return exhaustive
    }
  }
}

export function orderSummary(id: string): string {
  const order = findOrder(id)

  if (!order) {
    return 'Missing order'
  }

  return `${order.customerEmail}: ${describeStatus(order.status)}`
}
